command_result.command:
cat > /tmp/run.sh <<'EOF'
# usage: run.sh name srcdir configure-args...
name=$1; src=$2; shift 2
b=/tmp/b/$name; rm -rf $b /tmp/i/$name; mkdir -p $b /tmp/i/$name
cd $b
$src/configure --prefix=/opt/$name "$@" >cfg.log 2>&1 || { echo CONFIGURE FAIL; tail -20 cfg.log; exit 1; }
make >mk.log 2>&1 || { echo MAKE FAIL; tail -30 mk.log; exit 1; }
make check >chk.log 2>&1 || { echo CHECK FAIL; tail -40 chk.log; exit 1; }
make install DESTDIR=/tmp/i/$name >inst.log 2>&1 || { echo INSTALL FAIL; tail -30 inst.log; exit 1; }
(cd /tmp/i/$name && find . | sort)
grep -rl /tmp/i /tmp/i/$name | head
EOF
rm -rf /tmp/b /tmp/i; sh /tmp/run.sh def /tmp/t/src 2>&1 | tail -50

cat > /tmp/full.sh <<'EOF'
name=$1; src=$2; shift 2
b=/tmp/b/$name; rm -rf $b /tmp/i/$name; mkdir -p $b /tmp/i/$name
cd $b
$src/configure --prefix=/opt/$name "$@" >cfg.log 2>&1 || { echo CONFIGURE FAIL; tail -20 cfg.log; exit 1; }
make >mk.log 2>&1 || { echo MAKE FAIL; tail -30 mk.log; exit 1; }
make check >chk.log 2>&1 || { echo CHECK FAIL; tail -40 chk.log; exit 1; }
grep -E '^# (TOTAL|PASS)' tests/test-suite.log chk.log | head -3
make install DESTDIR=/tmp/i/$name >inst.log 2>&1 || { echo INSTALL FAIL; tail -30 inst.log; exit 1; }
(cd /tmp/i/$name && find . \( -type f -o -type l \) | sort)
grep -rl /tmp/i /tmp/i/$name | head
make uninstall DESTDIR=/tmp/i/$name >un.log 2>&1 || { echo UNINSTALL FAIL; tail -30 un.log; }
echo leftover:; (cd /tmp/i/$name && find . \( -type f -o -type l \))
make install DESTDIR=/tmp/i/$name >inst.log 2>&1
rm -rf /opt/$name; mkdir -p /opt; cp -a /tmp/i/$name/opt/$name /opt/$name 2>/dev/null || cp -a /tmp/i/$name/$(ls /tmp/i/$name | head -1) /opt/
EOF
rm -rf /tmp/t; mkdir /tmp/t; cp -r /app /tmp/t/src; cd /tmp/t/src; autoreconf -fi >/dev/null 2>&1; sh /tmp/full.sh def /tmp/t/src 2>&1 | tail -50; cat /opt/def/lib/pkgconfig/isodur.pc; ls -l /opt/def/bin; /opt/def/bin/isodur --version; /opt/def/bin/durfmt --style long PT36H5M; /opt/def/bin/isodur parse P1DT2.5S

nm -D --defined-only /opt/def/lib/libisodur.so | grep -v ' [wUbBdD] \| _'; readelf -d /opt/def/lib/libisodur.so | grep -i 'soname\|NEEDED'; cd /tmp && cat > app.c <<'EOF'
#include <isodur/isodur.h>
#include <stdio.h>
int main(void){isodur_t d; int r=isodur_parse("PT1.5S",&d); printf("%d %lld %s\n",r,isodur_total_ms(&d),isodur_version());return 0;}
EOF
export PKG_CONFIG_PATH=/opt/def/lib/pkgconfig; gcc app.c -o app_sh $(pkg-config --cflags --libs isodur) && LD_LIBRARY_PATH=/opt/def/lib ./app_sh; gcc app.c -o app_st $(pkg-config --cflags isodur) -static $(pkg-config --static --libs isodur) && ./app_st; pkg-config --variable=pkgdatadir isodur; strings /opt/def/bin/isodur | grep units
